template <typename T, typename... Is, typename... Js, typename ResultType=detail::merged_t<AA<T,Is...>, AA<T,Js...>>>
__host__ __device__ ResultType operator+(const AA<T,Is...>& lhs, const AA<T,Js...>& rhs);

template <typename T, typename... Is, typename... Js, typename ResultType=detail::merged_t<AA<T,Is...>, AA<T,Js...>>>
__host__ __device__ ResultType operator-(const AA<T,Is...>& lhs, const AA<T,Js...>& rhs);

template <typename T, typename... Is, typename... Js, typename ResultType=detail::binop_result_t<AA<T,Is...>, AA<T,Js...>, op::MUL>>
__host__ __device__ ResultType operator*(const AA<T,Is...>& lhs, const AA<T,Js...>& rhs);

template <typename T, typename... Is>
__host__ __device__ auto operator/(const T& lhs, const AA<T,Is...>& rhs);

template <typename T, typename... Is, typename... Js>
__host__ __device__ auto operator/(const AA<T,Is...>& lhs, const AA<T,Js...>& rhs);


/* Functions that introduce a new noise symbol.
   Inputs outside of the domain of the function produce entire forms, except for sqrt, pow and acosh
   that are evaluated on the part of their input inside their domain when it is not empty. */
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::RECIPROCAL> reciprocal(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::SQRT> sqrt(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::EXP>  exp(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::LOG>  log(const AA<T,Is...>& x);

/* x^n for an integer n, sqr(x) = x^2 is tighter than x*x */
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::POWN> pow(const AA<T,Is...>& x, int n);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::POWN> sqr(const AA<T,Is...>& x);

/* x^y for a real y, defined for x >= 0 (x > 0 if y < 0) */
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::POW> pow(const AA<T,Is...>& x, const detail::identity_t<T>& y);

template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::SIN> sin(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::COS> cos(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::TAN> tan(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::COT> cot(const AA<T,Is...>& x);

template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::SINH>  sinh(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::COSH>  cosh(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::TANH>  tanh(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::ASINH> asinh(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::ACOSH> acosh(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::ATANH> atanh(const AA<T,Is...>& x);

/* |x| and max(x, 0) */
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::ABS> abs(const AA<T,Is...>& x);
template <typename T, typename... Is> __host__ __device__ unop_result_t<AA<T,Is...>, op::POSITIVE_PART> positive_part(const AA<T,Is...>& x);


/* other operators */
#ifndef __CUDACC_RTC__
    template <typename T, typename... Is>
    __host__ std::ostream& operator<<(std::ostream& os, const AA<T,Is...>& val);
#endif


/* implementation */
template <typename T, typename... Is>
AA<T,Is...>::AA(const T& b): m_b(b), m_x{}, m_tag{}, m_err(0) {}

template <typename T, typename... Is>
AA<T,Is...>::AA(const Interval<T>& interval): m_b(0), m_x{}, m_tag{}, m_err(0) {
    static_assert(N==1, "Can only construct from interval when there is only one noise symbol.");
    if (!detail::is_finite(interval.a) || !detail::is_finite(interval.b)) {
        this->set_entire();
        return;
    }
    /* enclose [a,b] */
    const T m = detail::add_rn(detail::mul_rn(interval.a, T(0.5)), detail::mul_rn(interval.b, T(0.5)));
    m_b = m;
    cuda::std::get<0>(m_x) = detail::fmax(detail::sub_up(interval.b, m), detail::sub_up(m, interval.a));
}

template <typename T, typename... Is>
template <int K>
__host__ __device__ AA<T,detail::id<K>> AA<T,Is...>::from_interval(const Interval<T>& interval) {
    return AA<T,detail::id<K>>(interval);
}

template <typename T, typename... Is>
template <int K>
size_t AA<T,Is...>::pretty_idx() {
    static_assert(K<N);
#ifdef __CUDACC_RTC__
    return K;
#else
#ifdef __CUDA_ARCH__
    return K;
#else
    return std::type_index(typeid(idx<K>)).hash_code();
#endif  /* __CUDA_ARCH__ */
#endif  /* __CUDACC_RTC__ */
}

template <typename T, typename... Is>
T& AA<T,Is...>::b() {
    return m_b;
}

template <typename T, typename... Is>
const T& AA<T,Is...>::b() const {
    return m_b;
}

template <typename T, typename... Is>
template <int K>
T& AA<T,Is...>::x() {
    static_assert(K<N);
    return cuda::std::get<K>(m_x);
}

template <typename T, typename... Is>
template <int K>
const T& AA<T,Is...>::x() const {
    static_assert(K<N);
    return cuda::std::get<K>(m_x);
}

template <typename T, typename... Is>
template <typename I>
T& AA<T,Is...>::x() {
    static_assert(has_symbol<I>());
    return x<symbol_offset<I>()>();
}

template <typename T, typename... Is>
template <typename I>
const T& AA<T,Is...>::x() const {
    static_assert(has_symbol<I>());
    return x<symbol_offset<I>()>();
}

template <typename T, typename... Is>
template <int K>
detail::tag_t& AA<T,Is...>::tag() {
    static_assert(K<N);
    return cuda::std::get<K>(m_tag);
}

template <typename T, typename... Is>
template <int K>
const detail::tag_t& AA<T,Is...>::tag() const {
    static_assert(K<N);
    return cuda::std::get<K>(m_tag);
}

template <typename T, typename... Is>
template <typename I>
detail::tag_t& AA<T,Is...>::tag() {
    static_assert(has_symbol<I>());
    return tag<symbol_offset<I>()>();
}

template <typename T, typename... Is>
template <typename I>
const detail::tag_t& AA<T,Is...>::tag() const {
    static_assert(has_symbol<I>());
    return tag<symbol_offset<I>()>();
}

template <typename T, typename... Is>
T& AA<T,Is...>::err() {
    return m_err;
}

template <typename T, typename... Is>
const T& AA<T,Is...>::err() const {
    return m_err;
}

template <typename T, typename... Is>
template <typename I>
__host__ __device__ constexpr bool AA<T,Is...>::has_symbol() {
    return detail::IdInSequence<I, Is...>::value;
}

template <typename T, typename... Is>
template <typename I>
__host__ __device__ constexpr int AA<T,Is...>::symbol_offset() {
    return detail::OffsetInSequence<I, detail::type_id_sequence<Is...>>::value;
}

template <typename T, typename... Is>
template <typename I, int D>
__host__ __device__ T AA<T,Is...>::symbol_magnitude() const {
    if constexpr (has_symbol<I>()) {
        return x<I>();
    }
    else {
        return T(D);
    }
}

template <typename T, typename... Is>
template <typename I>
__host__ __device__ detail::tag_t AA<T,Is...>::symbol_tag() const {
    if constexpr (has_symbol<I>()) {
        return tag<I>();
    }
    else {
        return detail::tag_t(0);
    }
}

template <typename T, typename... Is>
__host__ __device__ detail::tag_t AA<T,Is...>::content_hash(detail::tag_t seed) const {
    return this->content_hash_impl(detail::hash_combine(seed, detail::bits(m_b)), detail::make_integer_sequence<N>{});
}

template <typename T, typename... Is>
template <int... Ks>
__host__ __device__ detail::tag_t AA<T,Is...>::content_hash_impl(detail::tag_t h, detail::integer_sequence<Ks...>) const {
    /* input symbols have constant zero tags, only hash magnitudes for those */
    ((h = detail::hash_combine(h, detail::bits(this->x<Ks>())),
      h = (detail::is_generated<idx<Ks>> ? detail::hash_combine(h, this->tag<Ks>()) : h)), ...);
    return h;
}

template <typename T, typename... Is>
template <typename Functor, typename... Args>
AA<T,Is...>& AA<T,Is...>::apply(Functor&& f, Args&&... args) {
    this->apply_impl(cuda::std::forward<Functor>(f), cuda::std::forward<Args>(args)..., detail::make_integer_sequence<N>{});
    return *this;
}

template <typename T, typename... Is>
template <typename Functor, typename... Args>
const AA<T,Is...>& AA<T,Is...>::apply(Functor&& f, Args&&... args) const {
    this->apply_impl(cuda::std::forward<Functor>(f), cuda::std::forward<Args>(args)..., detail::make_integer_sequence<N>{});
    return *this;
}

template <typename T, typename... Is>
template <typename Functor, typename... Args, int... Ks>
void AA<T,Is...>::apply_impl(Functor&& f, Args&&... args, detail::integer_sequence<Ks...>) {
    (f(Ks, this->x<Ks>(), args...), ...);
}

template <typename T, typename... Is>
template <typename Functor, typename... Args, int... Ks>
void AA<T,Is...>::apply_impl(Functor&& f, Args&&... args, detail::integer_sequence<Ks...>) const {
    (f(Ks, this->x<Ks>(), args...), ...);
}

template <typename T, typename... Is>
template <template <int> class Functor, typename... Args>
const AA<T,Is...>& AA<T,Is...>::constexpr_apply(Args&&... args) const {
    if constexpr (N > 0) {
        this->constexpr_apply_impl<Functor,0,Args...>(cuda::std::forward<Args>(args)...);
    }
    return *this;
}

template <typename T, typename... Is>
template <template <int> class Functor, int K, typename... Args>
void AA<T,Is...>::constexpr_apply_impl(Args&&... args) const {
    Functor<K>()(*this, args...);
    if constexpr (K+1<N) {
        this->constexpr_apply_impl<Functor,K+1,Args...>(cuda::std::forward<Args>(args)...);
    }
}

template <typename T, typename... Is>
template <template <int> class Functor, typename... Args>
AA<T,Is...>& AA<T,Is...>::constexpr_apply(Args&&... args) {
    if constexpr (N > 0) {
        this->constexpr_apply_impl<Functor,0,Args...>(cuda::std::forward<Args>(args)...);
    }
    return *this;
}

template <typename T, typename... Is>
template <template <int> class Functor, int K, typename... Args>
void AA<T,Is...>::constexpr_apply_impl(Args&&... args) {
    Functor<K>()(*this, args...);
    if constexpr (K+1<N) {
        this->constexpr_apply_impl<Functor,K+1,Args...>(cuda::std::forward<Args>(args)...);
    }
}

template <typename T, typename... Is>
T AA<T,Is...>::affine_radius() const {
    T r(0);
    this->apply([&](int k, const T& xi) { r = detail::add_up(r, T(::fabs(xi))); });
    return r;
}

template <typename T, typename... Is>
T AA<T,Is...>::radius() const {
    return detail::add_up(this->affine_radius(), m_err);
}

namespace impl {
    template <typename T>
    __host__ __device__ inline Interval<T> centered_interval(const T c, const T r) {
        if (detail::is_nan(c) || detail::is_nan(r) || !detail::is_finite(c)) {
            return Interval<T>(-detail::infinity<T>(), detail::infinity<T>());
        }
        return Interval<T>(detail::sub_down(c, r), detail::add_up(c, r));
    }
}

template <typename T, typename... Is>
AA<T,Is...>::operator Interval<T>() const {
    return impl::centered_interval(m_b, this->radius());
}

template <typename T, typename... Is>
Interval<T> AA<T,Is...>::interval() const {
    return Interval<T>(*this);
}

template <typename T, typename... Is>
Interval<T> AA<T,Is...>::affine_interval() const {
    return impl::centered_interval(m_b, this->affine_radius());
}

template <typename T, typename... Is>
Sign AA<T,Is...>::sign() const {
    return this->interval().sign();
}

template <typename T, typename... Is>
bool AA<T,Is...>::is_entire() const {
    const Interval<T> i = this->interval();
    return !(detail::is_finite(i.a) && detail::is_finite(i.b));
}

template <typename T, typename... Is>
void AA<T,Is...>::set_entire() {
    m_b = T(0);
    m_x = {};
    m_tag = {};
    m_err = detail::infinity<T>();
}

template <typename T, typename... Is>
AA<T,Is...> AA<T,Is...>::operator+() const {
    return AA<T,Is...>(*this);
}

template <typename T, typename... Is>
AA<T,Is...> AA<T,Is...>::operator-() const {
    AA<T,Is...> out(*this);
    out.b() = -out.b();
    return out.apply([](int k, T& xi) { xi = -xi; });
}


namespace impl {
    /* exact (or upper bounds of) rounding errors of s = add_rn(a,b), p = mul_rn(a,b) and q = div_rn(a,b) */
    template <typename T>
    __host__ __device__ inline T add_error(const T a, const T b, const T s) {
        if (a == T(0) || b == T(0)) { return T(0); }
        return ::fabs(detail::two_sum_error(a, b, s));
    }

    template <typename T>
    __host__ __device__ inline T mul_error(const T a, const T b, const T p) {
        if (a == T(0) || b == T(0)) { return T(0); }
        if (!detail::is_finite(p) || ::fabs(p) < detail::fp<T>::tiny()) { return detail::error_bound(p); }
        return ::fabs(detail::two_prod_error(a, b, p));
    }

    template <typename T>
    __host__ __device__ inline T div_error(const T a, const T b, const T q) {
        if (a == T(0)) { return T(0); }
        if (!detail::is_finite(q) || ::fabs(q) < detail::fp<T>::tiny() || ::fabs(a) < detail::fp<T>::tiny()) {
            return detail::error_bound(q);
        }
        return detail::div_up(T(::fabs(::fma(-q, b, a))), T(::fabs(b)));
    }
}

template <typename T, typename... Is>
AA<T,Is...>& AA<T,Is...>::operator+=(const T& other)  {
    const T s = detail::add_rn(m_b, other);
    m_err = detail::add_up(m_err, impl::add_error(m_b, other, s));
    m_b = s;
    return *this;
}

template <typename T, typename... Is>
AA<T,Is...>& AA<T,Is...>::operator-=(const T& other)  {
    return (*this += (-other));
}

template <typename T, typename... Is>
AA<T,Is...>& AA<T,Is...>::operator*=(const T& other)  {
    T e = detail::mul_up(m_err, T(::fabs(other)));
    const T p = detail::mul_rn(m_b, other);
    e = detail::add_up(e, impl::mul_error(m_b, other, p));
    m_b = p;
    this->apply([&](int k, T& xi) {
        const T q = detail::mul_rn(xi, other);
        e = detail::add_up(e, impl::mul_error(xi, other, q));
        xi = q;
    });
    m_err = e;
    return *this;
}

template <typename T, typename... Is>
AA<T,Is...>& AA<T,Is...>::operator/=(const T& other)  {
    T e = detail::div_up(m_err, T(::fabs(other)));
    const T p = detail::div_rn(m_b, other);
    e = detail::add_up(e, impl::div_error(m_b, other, p));
    m_b = p;
    this->apply([&](int k, T& xi) {
        const T q = detail::div_rn(xi, other);
        e = detail::add_up(e, impl::div_error(xi, other, q));
        xi = q;
    });
    m_err = e;
    return *this;
}

namespace impl {
    /* runtime tag of a new symbol introduced by operation opcode */
    __host__ __device__ inline detail::tag_t seed(int opcode) {
        return detail::hash_combine(detail::tag_t(0), detail::tag_t(opcode));
    }

    /* Linear combination l*eps_l + r*eps_r of two occurences of noise symbol I with tags ltag and rtag.
       Input symbols, or generated symbols with the same tag, represent the same quantity (eps_l == eps_r).
       Otherwise eps_l and eps_r are two different generated quantities that happen to share the same
       symbol type, they are merged into a new symbol with magnitude |l|+|r| (and a new tag).
       Returns the rounding error. */
    template <typename I, typename T>
    __host__ __device__ T combine_symbol(T& out, detail::tag_t& out_tag,
            const T l, const detail::tag_t ltag, const T r, const detail::tag_t rtag) {
        if (r == T(0)) {
            out = l;
            out_tag = ltag;
            return T(0);
        }
        if (l == T(0)) {
            out = r;
            out_tag = rtag;
            return T(0);
        }
        if constexpr (detail::is_generated<I>) {
            if (ltag != rtag) {
                out = detail::add_up(T(::fabs(l)), T(::fabs(r)));
                detail::tag_t h = seed(op::MERGE);
                h = detail::hash_combine(h, ltag);
                h = detail::hash_combine(h, detail::bits(l));
                h = detail::hash_combine(h, rtag);
                h = detail::hash_combine(h, detail::bits(r));
                out_tag = h;
                return T(0);
            }
        }
        const T s = detail::add_rn(l, r);
        out = s;
        out_tag = ltag;
        return add_error(l, r, s);
    }

    template <int K>
    struct inplace_add_functor {
        template <typename T, typename... Is>
        __host__ __device__ void operator()(AA<T,Is...>& lhs, const AA<T,Is...>& rhs) const {
            using I = typename AA<T,Is...>::template idx<K>;
            const T e = combine_symbol<I>(lhs.template x<K>(), lhs.template tag<K>(),
                    lhs.template x<K>(), lhs.template tag<K>(),
                    rhs.template x<K>(), rhs.template tag<K>());
            lhs.err() = detail::add_up(lhs.err(), e);
        }
    };

    template <int K>
    struct inplace_subtract_functor {
        template <typename T, typename... Is>
        __host__ __device__ void operator()(AA<T,Is...>& lhs, const AA<T,Is...>& rhs) const {
            using I = typename AA<T,Is...>::template idx<K>;
            const T e = combine_symbol<I>(lhs.template x<K>(), lhs.template tag<K>(),
                    lhs.template x<K>(), lhs.template tag<K>(),
                    -rhs.template x<K>(), rhs.template tag<K>());
            lhs.err() = detail::add_up(lhs.err(), e);
        }
    };

    template <int K>
    struct outplace_add_functor {
        template <typename T, typename... Is, typename... Js, typename... Ks>
        __host__ __device__ void operator()(AA<T,Is...>& out, const AA<T,Js...>& lhs, const AA<T,Ks...>& rhs) const {
            using I = typename AA<T,Is...>::template idx<K>;
            const T e = combine_symbol<I>(out.template x<K>(), out.template tag<K>(),
                    lhs.template symbol_magnitude<I,0>(), lhs.template symbol_tag<I>(),
                    rhs.template symbol_magnitude<I,0>(), rhs.template symbol_tag<I>());
            out.err() = detail::add_up(out.err(), e);
        }
    };

    template <int K>
    struct outplace_subtract_functor {
        template <typename T, typename... Is, typename... Js, typename... Ks>
        __host__ __device__ void operator()(AA<T,Is...>& out, const AA<T,Js...>& lhs, const AA<T,Ks...>& rhs) const {
            using I = typename AA<T,Is...>::template idx<K>;
            const T e = combine_symbol<I>(out.template x<K>(), out.template tag<K>(),
                     lhs.template symbol_magnitude<I,0>(), lhs.template symbol_tag<I>(),
                    -rhs.template symbol_magnitude<I,0>(), rhs.template symbol_tag<I>());
            out.err() = detail::add_up(out.err(), e);
        }
    };

    template <int K>
    struct outplace_multiply_functor {
        template <typename T, typename... Is, typename... Js, typename... Ks>
        __host__ __device__ void operator()(AA<T,Is...>& out, const AA<T,Js...>& lhs, const AA<T,Ks...>& rhs,
                const detail::tag_t new_tag, const T new_magnitude) const {
            using I = typename AA<T,Is...>::template idx<K>;
            if constexpr (AA<T,Js...>::template has_symbol<I>() || AA<T,Ks...>::template has_symbol<I>()) {
                const T lx = lhs.template symbol_magnitude<I,0>();
                const T rx = rhs.template symbol_magnitude<I,0>();
                const T l = detail::mul_rn(lx, rhs.b());
                const T r = detail::mul_rn(rx, lhs.b());
                const T e = combine_symbol<I>(out.template x<I>(), out.template tag<I>(),
                        l, lhs.template symbol_tag<I>(), r, rhs.template symbol_tag<I>());
                out.err() = detail::add_up(out.err(),
                        detail::add_up(e, detail::add_up(mul_error(lx, rhs.b(), l), mul_error(rx, lhs.b(), r))));
            }
            else {
                out.template x<I>() = new_magnitude;
                out.template tag<I>() = new_tag;
            }
        }
    };

    template <int K>
    struct affine_functor {
        template <typename T, typename... Is, typename... Js>
        __host__ __device__ void operator()(AA<T,Is...>& out, const AA<T,Js...>& base,
                const T alpha, const T delta, const detail::tag_t new_tag) const {
            using I = typename AA<T,Is...>::template idx<K>;
            if constexpr (AA<T,Js...>::template has_symbol<I>()) {
                const T x = base.template x<I>();
                const T p = detail::mul_rn(alpha, x);
                out.template x<I>() = p;
                out.template tag<I>() = base.template tag<I>();
                out.err() = detail::add_up(out.err(), mul_error(alpha, x, p));
            }
            else {
                out.template x<I>() = delta;
                out.template tag<I>() = new_tag;
            }
        }
    };

    template <int K>
    struct print_functor {
        template <typename T, typename... Is>
        __host__ __device__ void operator()(const AA<T,Is...>& val) const {
            using V = AA<T,Is...>;
            printf("%3i: %+2.1e", int(V::template pretty_idx<K>() & 0xff), double(val.template x<K>()));
            if (K != V::N-1) { printf(", "); }
        }
    };

#ifndef __CUDACC_RTC__
    template <int K>
    struct ostream_functor {
        template <typename T, typename... Is>
        __host__ __device__ void operator()(const AA<T,Is...>& val, std::ostream& os) const {
#ifndef __CUDA_ARCH__
            using V = AA<T,Is...>;
            os << (V::template pretty_idx<K>() & 0xff) << ": " << val.template x<K>();
            if constexpr (K != V::N-1) {
                os << ", ";
            }
#endif /* endif __CUDA_ARCH__ */
        }
    };
#endif /* endif __CUDACC_RTC__ */

} /* end of namespace impl */

template <typename T, typename... Is>
AA<T,Is...>& AA<T,Is...>::operator+=(const AA<T,Is...>& other)  {
    const T s = detail::add_rn(m_b, other.b());
    m_err = detail::add_up(detail::add_up(m_err, other.err()), impl::add_error(m_b, other.b(), s));
    m_b = s;
    return this->constexpr_apply<impl::inplace_add_functor>(other);
}

template <typename T, typename... Is>
AA<T,Is...>& AA<T,Is...>::operator-=(const AA<T,Is...>& other)  {
    const T s = detail::sub_rn(m_b, other.b());
    m_err = detail::add_up(detail::add_up(m_err, other.err()), impl::add_error(m_b, -other.b(), s));
    m_b = s;
    return this->constexpr_apply<impl::inplace_subtract_functor>(other);
}

template <typename T, typename... Is>
__host__ __device__ AA<T,Is...> operator+(const AA<T,Is...>& lhs, const AA<T,Is...>& rhs) {
    return +lhs += rhs;
}

template <typename T, typename... Is>
__host__ __device__ AA<T,Is...> operator+(const AA<T,Is...>& lhs, const T& rhs) {
    return +lhs += rhs;
}

template <typename T, typename... Is>
__host__ __device__ AA<T,Is...> operator+(const T& lhs, const AA<T,Is...>& rhs) {
    return +rhs += lhs;
}

template <typename T, typename... Is>
__host__ __device__ AA<T,Is...> operator-(const AA<T,Is...>& lhs, const AA<T,Is...>& rhs) {
    return +lhs -= rhs;
}

template <typename T, typename... Is>
__host__ __device__ AA<T,Is...> operator-(const AA<T,Is...>& lhs, const T& rhs) {
    return +lhs -= rhs;
}

template <typename T, typename... Is>
__host__ __device__ AA<T,Is...> operator-(const T& lhs, const AA<T,Is...>& rhs) {
    return -rhs += lhs;
}

template <typename T, typename... Is>
__host__ __device__ AA<T,Is...> operator*(const AA<T,Is...>& lhs, const T& rhs) {
    return +lhs *= rhs;
}

template <typename T, typename... Is>
__host__ __device__ AA<T,Is...> operator*(const T& lhs, const AA<T,Is...>& rhs) {
    return +rhs *= lhs;
}

template <typename T, typename... Is>
__host__ __device__ AA<T,Is...> operator/(const AA<T,Is...>& lhs, const T& rhs) {
    return +lhs /= rhs;
}

template <typename T, typename... Is, typename... Js, typename ResultType>
__host__ __device__ ResultType operator+(const AA<T,Is...>& lhs, const AA<T,Js...>& rhs) {
    const T s = detail::add_rn(lhs.b(), rhs.b());
    ResultType out(s);
    out.err() = detail::add_up(detail::add_up(lhs.err(), rhs.err()), impl::add_error(lhs.b(), rhs.b(), s));
    return out.template constexpr_apply<impl::outplace_add_functor>(lhs, rhs);
}

template <typename T, typename... Is, typename... Js, typename ResultType>
__host__ __device__ ResultType operator-(const AA<T,Is...>& lhs, const AA<T,Js...>& rhs) {
    const T s = detail::sub_rn(lhs.b(), rhs.b());
    ResultType out(s);
    out.err() = detail::add_up(detail::add_up(lhs.err(), rhs.err()), impl::add_error(lhs.b(), -rhs.b(), s));
    return out.template constexpr_apply<impl::outplace_subtract_functor>(lhs, rhs);
}

template <typename T, typename... Is, typename... Js, typename ResultType>
__host__ __device__ ResultType operator*(const AA<T,Is...>& lhs, const AA<T,Js...>& rhs) {
    /* (lb + L + el)(rb + R + er) = lb*rb + lb*R + rb*L + L*R + (lb+L)*er + (rb+R)*el + el*er
       where L*R is attached to the new symbol and the last three terms to the error term */
    const T p = detail::mul_rn(lhs.b(), rhs.b());
    ResultType out(p);

    const T lr = lhs.affine_radius();
    const T rr = rhs.affine_radius();
    T e = impl::mul_error(lhs.b(), rhs.b(), p);
    if (lhs.err() != T(0) || rhs.err() != T(0)) {
        const T lm = detail::add_up(T(::fabs(lhs.b())), lr);
        const T rm = detail::add_up(T(::fabs(rhs.b())), rr);
        e = detail::add_up(e, detail::add_up(detail::mul_up(rm, lhs.err()), detail::mul_up(lm, rhs.err())));
        e = detail::add_up(e, detail::mul_up(lhs.err(), rhs.err()));
    }
    out.err() = e;

    const detail::tag_t new_tag = rhs.content_hash(lhs.content_hash(impl::seed(op::MUL)));
    return out.template constexpr_apply<impl::outplace_multiply_functor>(lhs, rhs, new_tag, detail::mul_up(lr, rr));
}

template <typename T, typename... Is>
__host__ __device__ auto operator/(const T& lhs, const AA<T,Is...>& rhs) {
    return lhs * reciprocal(rhs);
}

template <typename T, typename... Is, typename... Js>
__host__ __device__ auto operator/(const AA<T,Is...>& lhs, const AA<T,Js...>& rhs) {
    return lhs * reciprocal(rhs);
}

namespace impl {
    /* Apply the approximation f(x) = alpha*x + zeta + delta*eps_new + err*eps_err. extra is hashed
       together with the content of x to tag the new symbol (parameters of the function). */
    template <int opcode, typename T, typename... Is>
    __host__ __device__ unop_result_t<AA<T,Is...>, opcode> apply_approx(const AA<T,Is...>& x,
            const detail::Approx<T>& A, const detail::tag_t extra = detail::tag_t(0)) {
        unop_result_t<AA<T,Is...>, opcode> out;
        if (A.entire) {
            out.set_entire();
            return out;
        }
        const T p = detail::mul_rn(A.alpha, x.b());
        const T s = detail::add_rn(p, A.zeta);
        out.b() = s;
        out.err() = detail::add_up(A.err, detail::add_up(mul_error(A.alpha, x.b(), p), add_error(p, A.zeta, s)));
        const detail::tag_t new_tag = x.content_hash(detail::hash_combine(seed(opcode), extra));
        return out.template constexpr_apply<affine_functor>(x, A.alpha, A.delta, new_tag);
    }
}

