__host__ __device__ unop_result_t<AA<T,Is...>, op::RECIPROCAL> reciprocal(const AA<T,Is...>& x) {
    return impl::apply_approx<op::RECIPROCAL>(x, detail::approx_reciprocal(x.affine_interval(), x.err()));
